1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Room bookings</title>
7	<style>
8	  :root { color-scheme: light dark; --accent: #2f6fdf; --muted: #6b7280; --danger: #c0392b; }
9	  * { box-sizing: border-box; }
10	  body { font: 16px/1.5 system-ui, sans-serif; max-width: 42rem; margin: 2rem auto; padding: 0 1rem; }
11	  h1 { font-size: 1.75rem; margin: 0 0 1.5rem; }
12	  h2 { font-size: 1.15rem; margin: 2rem 0 0.75rem; }
13	  form { display: grid; grid-template-columns: max-content 1fr; gap: 0.6rem 1rem; align-items: center; }
14	  label { font-weight: 600; }
15	  input, select, button { font: inherit; padding: 0.4rem 0.6rem; border: 1px solid var(--muted); border-radius: 6px; }
16	  button { cursor: pointer; background: var(--accent); color: #fff; border-color: var(--accent); }
17	  button:disabled { opacity: 0.55; cursor: progress; }
18	  button:focus-visible, input:focus-visible, select:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
19	  #book { grid-column: 2; justify-self: start; }
20	  .filter { display: flex; flex-wrap: wrap; gap: 0.6rem; align-items: center; }
21	  #show-all { background: transparent; color: var(--accent); }
22	  #booking-list { list-style: none; padding: 0; margin: 1rem 0 0; }
23	  #booking-list li { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: 0.5rem 0; border-bottom: 1px solid color-mix(in srgb, var(--muted) 35%, transparent); }
24	  #booking-list li button { background: transparent; color: var(--danger); border-color: var(--danger); padding: 0.2rem 0.6rem; }
25	  #error { color: var(--danger); font-weight: 600; min-height: 1.5em; }
26	</style>
27	</head>
28	<body>
29	<main>
30	<h1>Room bookings</h1>
31	<form id="booking-form" novalidate>
32	  <label for="room">Room</label>
33	  <select id="room" name="room"></select>
34	  <label for="title">Title</label>
35	  <input type="text" id="title" name="title" autocomplete="off">
36	  <label for="date">Date</label>
37	  <input type="date" id="date" name="date">
38	  <label for="start">Start</label>
39	  <input type="time" id="start" name="start">
40	  <label for="end">End</label>
41	  <input type="time" id="end" name="end">
42	  <button type="submit" id="book">Book</button>
43	</form>
44	<p id="error" role="alert"></p>
45	<h2>Bookings</h2>
46	<div class="filter">
47	  <label for="filter-date">Show date</label>
48	  <input type="date" id="filter-date">
49	  <button type="button" id="show-all">Show all</button>
50	</div>
51	<ul id="booking-list"></ul>
52	</main>
53	<script src="/app.js"></script>
54	</body>
55	</html>
