1	(function () {
2	  'use strict';
3	
4	  var NO_REPLY = 'Could not reach the server.';
5	  var FALLBACK = 'Request failed.';
6	
7	  var form = document.getElementById('booking-form');
8	  var roomSelect = document.getElementById('room');
9	  var titleInput = document.getElementById('title');
10	  var dateInput = document.getElementById('date');
11	  var startInput = document.getElementById('start');
12	  var endInput = document.getElementById('end');
13	  var bookButton = document.getElementById('book');
14	  var filterInput = document.getElementById('filter-date');
15	  var showAllButton = document.getElementById('show-all');
16	  var list = document.getElementById('booking-list');
17	  var errorBox = document.getElementById('error');
18	
19	  var listSequence = 0;
20	
21	  // Resolves to { reached: false } when there is no usable reply, otherwise
22	  // { reached: true, status, body }. A 204 body is never read; any other body
23	  // that cannot be read or parsed as JSON counts as no reply.
24	  async function request(url, options) {
25	    var reply;
26	    try {
27	      reply = await fetch(url, options);
28	    } catch (failure) {
29	      return { reached: false, failure: failure };
30	    }
31	    if (reply.status === 204) {
32	      return { reached: true, status: 204, body: null };
33	    }
34	    try {
35	      return { reached: true, status: reply.status, body: await reply.json() };
36	    } catch (failure) {
37	      return { reached: false, failure: failure };
38	    }
39	  }
40	
41	  function isPlainObject(value) {
42	    return value !== null && typeof value === 'object' && !Array.isArray(value);
43	  }
44	
45	  function errorMessage(body) {
46	    return isPlainObject(body) && typeof body.error === 'string' ? body.error : FALLBACK;
47	  }
48	
49	  function showError(text) {
50	    errorBox.textContent = text;
51	  }
52	
53	  function showOutcomeError(outcome) {
54	    showError(outcome.reached ? errorMessage(outcome.body) : NO_REPLY);
55	  }
56	
57	  function listUrl() {
58	    var date = filterInput.value;
59	    return date === '' ? '/api/bookings' : '/api/bookings?date=' + date;
60	  }
61	
62	  function bookingText(booking) {
63	    return booking.date + ' ' + booking.start + '-' + booking.end + ' ' +
64	      booking.room + ': ' + booking.title;
65	  }
66	
67	  function bookingItem(booking) {
68	    var item = document.createElement('li');
69	    var cancel = document.createElement('button');
70	    cancel.type = 'button';
71	    cancel.textContent = 'Cancel';
72	    cancel.addEventListener('click', function () {
73	      cancelBooking(booking.id, cancel);
74	    });
75	    item.append(bookingText(booking), cancel);
76	    return item;
77	  }
78	
79	  function renderList(bookings) {
80	    if (bookings.length === 0) {
81	      var empty = document.createElement('li');
82	      empty.append('No bookings.');
83	      list.replaceChildren(empty);
84	      return;
85	    }
86	    list.replaceChildren(...bookings.map(bookingItem));
87	  }
88	
89	  async function loadList() {
90	    listSequence += 1;
91	    var mine = listSequence;
92	    var outcome = await request(listUrl());
93	    if (mine !== listSequence) {
94	      return;
95	    }
96	    if (outcome.reached && outcome.status === 200 &&
97	        isPlainObject(outcome.body) && Array.isArray(outcome.body.bookings)) {
98	      renderList(outcome.body.bookings);
99	      return;
100	    }
101	    showOutcomeError(outcome);
102	  }
103	
104	  function fillRooms(rooms) {
105	    rooms.forEach(function (name) {
106	      var option = document.createElement('option');
107	      option.value = name;
108	      option.textContent = name;
109	      roomSelect.append(option);
110	    });
111	  }
112	
113	  async function loadRooms() {
114	    var outcome = await request('/api/rooms');
115	    if (outcome.reached && outcome.status === 200 &&
116	        isPlainObject(outcome.body) && Array.isArray(outcome.body.rooms)) {
117	      fillRooms(outcome.body.rooms);
118	      return;
119	    }
120	    showOutcomeError(outcome);
121	  }
122	
123	  function bookingPayload() {
124	    return JSON.stringify({
125	      room: roomSelect.value,
126	      title: titleInput.value,
127	      date: dateInput.value,
128	      start: startInput.value,
129	      end: endInput.value
130	    });
131	  }
132	
133	  async function submitBooking(event) {
134	    event.preventDefault();
135	    if (bookButton.disabled) {
136	      return;
137	    }
138	    bookButton.disabled = true;
139	    var outcome = await request('/api/bookings', {
140	      method: 'POST',
141	      headers: { 'Content-Type': 'application/json' },
142	      body: bookingPayload()
143	    });
144	    bookButton.disabled = false;
145	    if (outcome.reached && outcome.status === 201) {
146	      titleInput.value = '';
147	      showError('');
148	      loadList();
149	      return;
150	    }
151	    showOutcomeError(outcome);
152	  }
153	
154	  async function cancelBooking(id, button) {
155	    button.disabled = true;
156	    var outcome = await request('/api/bookings/' + id, { method: 'DELETE' });
157	    button.disabled = false;
158	    if (!outcome.reached) {
159	      showError(NO_REPLY);
160	      return;
161	    }
162	    showError(outcome.status === 204 ? '' : errorMessage(outcome.body));
163	    loadList();
164	  }
165	
166	  function showAll() {
167	    filterInput.value = '';
168	    loadList();
169	  }
170	
171	  form.addEventListener('submit', submitBooking);
172	  filterInput.addEventListener('change', loadList);
173	  showAllButton.addEventListener('click', showAll);
174	
175	  loadRooms();
176	  loadList();
177	}());
